import{_ as a,o as d,c as e,a2 as o}from"./chunks/framework.CqpfiAoK.js";const q=JSON.parse('{"title":"তল অতিক্রম নিয়ম","description":"","frontmatter":{},"headers":[],"relativePath":"bn/81-位面穿梭规则.md","filePath":"bn/81-位面穿梭规则.md"}'),r={name:"bn/81-位面穿梭规则.md"};function l(i,t,h,n,u,s){return d(),e("div",null,[...t[0]||(t[0]=[o('<h1 id="তল-অতিক্রম-নিয়ম" tabindex="-1">তল অতিক্রম নিয়ম <a class="header-anchor" href="#তল-অতিক্রম-নিয়ম" aria-label="Permalink to &quot;তল অতিক্রম নিয়ম&quot;">​</a></h1><table tabindex="0"><thead><tr><th>আইটেম</th><th>বিষয়বস্তু</th></tr></thead><tbody><tr><td>নথি নম্বর</td><td>81</td></tr><tr><td>মডিউল</td><td>আন্তঃ-তল মিথস্ক্রিয়া ও সময় নিয়ম</td></tr><tr><td>মূল কীওয়ার্ড</td><td>তল অতিক্রম, অতিক্রম অনুমতি, শক্তি সীমা, অ্যাঙ্কর অ্যালাইনমেন্ট, দূষণ প্রতিরোধ</td></tr></tbody></table><h2 id="_1-অতিক্রম-আচরণের-আইনি-অবস্থান" tabindex="-1">1. অতিক্রম আচরণের আইনি অবস্থান <a class="header-anchor" href="#_1-অতিক্রম-আচরণের-আইনি-অবস্থান" aria-label="Permalink to &quot;1. অতিক্রম আচরণের আইনি অবস্থান&quot;">​</a></h2><p>তল অতিক্রম বলতে জীব ব্যক্তি বা গোষ্ঠীর প্রযুক্তিগত উপায় বা সাধনা ক্ষমতার মাধ্যমে আইন প্রাচীর অতিক্রম করে এক তল থেকে অন্য তলে প্রবেশের আচরণকে বোঝায়। অ্যাঙ্কর সিম্বায়োসিস সভ্যতার আইনি কাঠামোর অধীনে, তল অতিক্রম &quot;উচ্চ-ঝুঁকি বিশেষ আচরণ&quot; এর অন্তর্গত, এবং এটিকে কঠোর অনুমতি ব্যবস্থাপনা ও প্রক্রিয়া তত্ত্বাবধানের অধীনে রাখতে হবে। &quot;সিম্বায়োসিস সংবিধান&quot; এর সপ্তাচল্লিশটি অনুচ্ছেদে স্পষ্টভাবে বলা হয়েছে: &quot;কোনো সংগঠন ও ব্যক্তি অনুমতি ছাড়া নিজের ইচ্ছায় আন্তঃ-তল অতিক্রম করতে পারবে না, এবং তল অতিক্রম ব্যবহার করে অন্য তলের সভ্যতার উপর লুণ্ঠন, হস্তক্ষেপ বা দূষণকারী কার্যকলাপ করতে পারবে না।&quot;</p><p>তল অতিক্রমকে কেন কঠোরভাবে নিয়ন্ত্রণ করতে হবে, তার মূল কারণ হলো অতিক্রম আচরণ নিজেই লক্ষ্য তলের উপর বহুমুখী প্রভাব ফেলতে পারে: আইন ব্যাঘাত, শক্তি ইনজেকশন, চেতনা দূষণ, অণুজীব আক্রমণ এবং সাংস্কৃতিক হস্তক্ষেপ ইত্যাদি। এই প্রভাবগুলি হালকা হলে লক্ষ্য তলের স্থানীয় অস্বাভাবিকতা সৃষ্টি করে, গুরুতর হলে এর সভ্যতার বিবর্তনের গতিপথ পরিবর্তন করতে পারে, এমনকি আইনের পতনের কারণ হতে পারে। অতএব, তল অতিক্রম নিয়মের মূল লক্ষ্য হলো &quot;অতিক্রম আচরণের বাহ্যিক প্রভাবকে গ্রহণযোগ্য সীমার মধ্যে নিয়ন্ত্রণ করা&quot;।</p><h2 id="_2-অতিক্রম-অনুমতি-শ্রেণীবিভাগ-ব্যবস্থা" tabindex="-1">2. অতিক্রম অনুমতি শ্রেণীবিভাগ ব্যবস্থা <a class="header-anchor" href="#_2-অতিক্রম-অনুমতি-শ্রেণীবিভাগ-ব্যবস্থা" aria-label="Permalink to &quot;2. অতিক্রম অনুমতি শ্রেণীবিভাগ ব্যবস্থা&quot;">​</a></h2><p>হেংইয়ান-ঝৌ তল অতিক্রম অনুমতি শ্রেণীবিভাগ ব্যবস্থা প্রয়োগ করে, অতিক্রমের উদ্দেশ্য, লক্ষ্য তলের ধরন এবং অতিক্রমকারীর যোগ্যতা অনুযায়ী অনুমতিকে চারটি শ্রেণীতে বিভক্ত করে:</p><table tabindex="0"><thead><tr><th>অনুমতির স্তর</th><th>প্রযোজ্য পরিস্থিতি</th><th>অনুমোদনকারী প্রতিষ্ঠান</th><th>মেয়াদ</th><th>অতিরিক্ত শর্ত</th></tr></thead><tbody><tr><td>A স্তর (প্রত্নতত্ত্ব পর্যবেক্ষণ)</td><td>বিশুদ্ধ পর্যবেক্ষণমূলক প্রত্নতত্ত্ব, কোনো ভৌত যোগাযোগ নেই</td><td>তল ব্যবস্থাপনা ব্যুরো</td><td>একক কাজ</td><td>অবশ্যই প্রতিলিপি দর্পণ + বিচ্ছিন্ন স্থান পরিকল্পনা ব্যবহার করতে হবে</td></tr><tr><td>B স্তর (শিক্ষাণু বিনিময়)</td><td>লক্ষ্য তলের সভ্যতার সাথে সীমিত জ্ঞান বিনিময়</td><td>তল ব্যবস্থাপনা ব্যুরো + সংস্কৃতি মন্ত্রণালয়</td><td>সর্বোচ্চ এক বছর</td><td>পরস্পর অহস্তক্ষেপ চুক্তি স্বাক্ষর করতে হবে</td></tr><tr><td>C স্তর (সম্পদ সহযোগিতা)</td><td>সমান ও পারস্পরিক লাভের ভিত্তিতে সম্পদ ও প্রযুক্তি সহযোগিতা</td><td>অ্যাঙ্কর কাউন্সিল বিশেষ অনুমোদন</td><td>সর্বোচ্চ তিন বছর</td><td>লক্ষ্য তলের সভ্যতার সম্মতি প্রাপ্ত করতে হবে</td></tr><tr><td>D স্তর (জরুরি হস্তক্ষেপ)</td><td>লক্ষ্য তলের বিলুপ্তি-স্তরের সংকটের সময় মানবিক হস্তক্ষেপ</td><td>অ্যাঙ্কর কাউন্সিল জরুরি সিদ্ধান্ত</td><td>সংকট চলাকালীন</td><td>পরে সম্পূর্ণ হস্তক্ষেপ রিপোর্ট জমা দিতে হবে</td></tr></tbody></table><p>যেকোনো স্তরের অতিক্রম অনুমতিতে নিম্নলিখিত আচরণ নিষিদ্ধ: লক্ষ্য তলের মূল শক্তি লুণ্ঠন করা, নিজের তলের মতাদর্শ জোর করে প্রচার করা, সম্মতি ছাড়া জিন বা চেতনা পরিবর্তন করা, লক্ষ্য তলে স্থায়ী সামরিক ঘাঁটি স্থাপন করা, এবং যেকোনো রূপের ঔপনিবেশিক শাসন।</p><h2 id="_3-অতিক্রম-প্রযুক্তির-প্রয়োজনীয়তা-ও-শক্তি-সীমা" tabindex="-1">3. অতিক্রম প্রযুক্তির প্রয়োজনীয়তা ও শক্তি সীমা <a class="header-anchor" href="#_3-অতিক্রম-প্রযুক্তির-প্রয়োজনীয়তা-ও-শক্তি-সীমা" aria-label="Permalink to &quot;3. অতিক্রম প্রযুক্তির প্রয়োজনীয়তা ও শক্তি সীমা&quot;">​</a></h2><p>তল অতিক্রমের জন্য কঠোর প্রযুক্তিগত শর্ত পূরণ করতে হয়। প্রথমত, অতিক্রমকারীর অবশ্যই &quot;স্থান আইন নিয়ন্ত্রণ ব্যবস্থা&quot; এর তৃতীয় স্তর (হুয়া কং জিং) বা তার বেশি সাধনা থাকতে হবে, অথবা মানক অনুযায়ী তল অতিক্রম বাহন বহন করতে হবে। দ্বিতীয়ত, অতিক্রমের সূচনা এবং শেষ উভয় স্থানেই অবশ্যই অ্যাঙ্কর দ্বারা স্থানাঙ্ক অ্যালাইনমেন্ট করতে হবে, অ্যাঙ্কর অবস্থান নির্ণয় ছাড়া অন্ধ অতিক্রম আচরণ কঠোরভাবে নিষিদ্ধ।</p><p>অতিক্রম প্রক্রিয়াতে শক্তির খরচ লক্ষ্য তলের আইন প্রাচীরের শক্তির সাথে সরাসরি সমানুপাতিক। হেংইয়ান-ঝৌ মানক &quot;অতিক্রম শক্তি সীমা সারণী&quot; প্রতিষ্ঠা করেছে, বিভিন্ন ধরনের তলের অতিক্রমের জন্য প্রয়োজনীয় সর্বনিম্ন শক্তি নিম্নরূপ:</p><ul><li>পদার্থ মূল তল: 1000 মানক শক্তি একক</li><li>শক্তি প্রকাশ তল: 5000 মানক শক্তি একক</li><li>চেতনা প্রধান তল: 20000 মানক শক্তি একক</li><li>আইন ভাঙা তল: 50000 মানক শক্তি একক (এবং সাফল্যের হার 30% এর নিচে)</li><li>মূল নিকটবর্তী তল: তাত্ত্বিক মান 100000 এর বেশি, বর্তমানে কোনো সাফল্যের রেকর্ড নেই</li></ul><p>অতিক্রম শক্তি অবশ্যই অতিক্রমকারী বা বাহন নিজেই বহন করতে হবে, অতিক্রম প্রক্রিয়ার জন্য লক্ষ্য তল থেকে শক্তি আহরণ করা নিষিদ্ধ। এই বিধানের উদ্দেশ্য হলো অতিক্রম আচরণের লক্ষ্য তলের উপর শক্তি লুণ্ঠন সৃষ্টি করা প্রতিরোধ করা।</p><h2 id="_4-অতিক্রম-প্রক্রিয়ার-দূষণ-প্রতিরোধ" tabindex="-1">4. অতিক্রম প্রক্রিয়ার দূষণ প্রতিরোধ <a class="header-anchor" href="#_4-অতিক্রম-প্রক্রিয়ার-দূষণ-প্রতিরোধ" aria-label="Permalink to &quot;4. অতিক্রম প্রক্রিয়ার দূষণ প্রতিরোধ&quot;">​</a></h2><p>তল অতিক্রমের সবচেয়ে বড় ঝুঁকির মধ্যে একটি হলো &quot;আন্তঃ-তল দূষণ&quot;, যার মধ্যে অন্তর্ভুক্ত জৈব দূষণ (নিজের তলের অণুজীব বহন করে লক্ষ্য তলে প্রবেশ), শক্তি দূষণ (নিজের তলের শক্তির অবশিষ্টাংশ লক্ষ্য তলের আইনে ব্যাঘাত) এবং চেতনা দূষণ (অতিক্রমকারীর চেতনার ওঠানামা লক্ষ্য তলের চেতনা ডোমেইনকে প্রভাবিত করা)।</p><p>দূষণ প্রতিরোধের জন্য, সব অতিক্রমকারীকে যাত্রা শুরুর আগে &quot;ত্রি-স্তর পরিশোধন প্রক্রিয়া&quot; সম্পন্ন করতে হবে:</p><ol><li><strong>জৈব পরিশোধন</strong>: বিচ্ছিন্ন স্থানে 72 ঘন্টার অণুজীব স্ক্রিনিং ও অপসারণ করা, নিশ্চিত করা যে কোনো নিজের তলের রোগজীবাণু বহন করছে না</li><li><strong>শক্তি পরিশোধন</strong>: অ্যাঙ্কর অ্যালাইনমেন্ট ডিভাইসের মাধ্যমে অতিক্রমকারীর শক্তির ফ্রিকোয়েন্সি লক্ষ্য তলের সাথে সামঞ্জস্যপূর্ণ পরিসরে সামঞ্জস্য করা, শক্তি বিক্রিয়া প্রতিক্রিয়া কমানো</li><li><strong>চেতনা পরিশোধন</strong>: চেতনা পর্দা প্রশিক্ষণ করা, নিশ্চিত করা যে অতিক্রম প্রক্রিয়াতে লক্ষ্য তলের চেতনা ডোমেইনকে ব্যাহত করতে পারে এমন ইচ্ছার ওঠানামা সক্রিয়ভাবে মুক্ত করে না</li></ol><p>এছাড়াও, লক্ষ্য তলে অতিক্রমকারীর কার্যকলাপের পরিসর কঠোরভাবে &quot;অতিক্রম অনুমতি দ্বারা নির্ধারিত অঞ্চল&quot; এর মধ্যে সীমাবদ্ধ, অননুমোদিত বিস্তার নিষিদ্ধ। নিজের তলে ফিরে আসার পর, অতিক্রমকারীকে আবার বিচ্ছিন্ন পর্যবেক্ষণে ভোগ করতে হবে, সময় কমপক্ষে লক্ষ্য তলের সময়ের প্রবাহের গতি অনুযায়ী রূপান্তরিত 30 দিন।</p><h2 id="উপসংহার" tabindex="-1">উপসংহার <a class="header-anchor" href="#উপসংহার" aria-label="Permalink to &quot;উপসংহার&quot;">​</a></h2><p>তল অতিক্রম নিয়ম হলো আন্তঃ-তল মিথস্ক্রিয়ার প্রথম সুরক্ষা প্রতিরক্ষা。 এটি অনুমতি শ্রেণীবিভাগ, প্রযুক্তিগত প্রবেশপথ এবং দূষণ প্রতিরোধ ত্রি-স্তরের প্রক্রিয়ার মাধ্যমে, নিশ্চিত করে যে অতিক্রম আচরণ সর্বদা &quot;কম প্রভাব, ট্রেসযোগ্য, দায়বদ্ধ&quot; পথে চলছে। নিয়মের চূড়ান্ত উদ্দেশ্য হলো সভ্যতার মধ্যে যোগাযোগকে সীমাবদ্ধ করা নয়, বরং যোগাযোগকে সিম্বায়োসিসের উপায়ে ঘটানো, লুণ্ঠনের উপায়ে নয়।</p><h2 id="সম্পর্কিত-নথি" tabindex="-1">সম্পর্কিত নথি <a class="header-anchor" href="#সম্পর্কিত-নথি" aria-label="Permalink to &quot;সম্পর্কিত নথি&quot;">​</a></h2><ul><li>80-তল তত্ত্ব ও শ্রেণীবিভাগ</li><li>88-আন্তঃ-তল নৈতিক নীতি</li><li>62-স্থান আইন প্রযুক্তি বাস্তবায়ন</li></ul>',23)])])}const p=a(r,[["render",l]]);export{q as __pageData,p as default};
